// The supplier's Parts tab. effective_unit is the explicit purchase unit, else the part's base
// unit; thumb_file as in parts.ListParts.
func (q *Queries) ListSupplierLinkedParts(ctx context.Context, arg ListSupplierLinkedPartsParams) ([]ListSupplierLinkedPartsRow, error) {
	rows, err := q.db.QueryContext(ctx, listSupplierLinkedParts, arg.ThumbCategory, arg.SupplierID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSupplierLinkedPartsRow
	for rows.Next() {
		var i ListSupplierLinkedPartsRow
		if err := rows.Scan(
			&i.ID,
			&i.PartID,
			&i.Preference,
			&i.SupplierPn,
			&i.SupplierDesc,
			&i.LeadTime,
			&i.MinIncrement,
			&i.PartNumber,
			&i.Description,
			&i.Revision,
			&i.Category,
			&i.UomID,
			&i.EffectiveUnit,
			&i.UnitIsExplicit,
			&i.ThumbFile,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

