const searchSuppliers = `-- name: SearchSuppliers :many
SELECT su.id, su.name, COALESCE(cn.city, '') AS city
FROM company su
LEFT JOIN contact cn ON su.default_contact = cn.id
WHERE su.name LIKE $1::text AND su.is_active = TRUE
  AND (NOT $2::boolean OR su.is_supplier = TRUE)
ORDER BY su.name
LIMIT $3::int
`

type SearchSuppliersParams struct {
	Pattern      string
	SupplierOnly bool
	N            int
}

type SearchSuppliersRow struct {
	ID   int
	Name string
	City string
}

// Typeahead: active companies whose name is LIKE pattern, with the default contact's city.
func (q *Queries) SearchSuppliers(ctx context.Context, arg SearchSuppliersParams) ([]SearchSuppliersRow, error) {
	rows, err := q.db.QueryContext(ctx, searchSuppliers, arg.Pattern, arg.SupplierOnly, arg.N)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchSuppliersRow
	for rows.Next() {
		var i SearchSuppliersRow
		if err := rows.Scan(&i.ID, &i.Name, &i.City); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateSupplier = `-- name: UpdateSupplier :exec
UPDATE company SET name = $1, supplier_code = $2::text,
       default_contact = $3,
       is_active = $4::boolean, is_supplier = $5::boolean,
       is_manufacturer = $6::boolean,
       notes = $7::text, date_modified = CURRENT_TIMESTAMP,
       bulk_order_delimiter = $8, bulk_order_pn_source = $9
WHERE id = $10
`

type UpdateSupplierParams struct {
	Name               string
	SupplierCode       string
	DefaultContact     *int
	IsActive           bool
	IsSupplier         bool
	IsManufacturer     bool
	Notes              string
	BulkOrderDelimiter string
	BulkOrderPnSource  string
	ID                 int
}

func (q *Queries) UpdateSupplier(ctx context.Context, arg UpdateSupplierParams) error {
	_, err := q.db.ExecContext(ctx, updateSupplier,
		arg.Name,
		arg.SupplierCode,
		arg.DefaultContact,
		arg.IsActive,
		arg.IsSupplier,
		arg.IsManufacturer,
		arg.Notes,
		arg.BulkOrderDelimiter,
		arg.BulkOrderPnSource,
		arg.ID,
	)
	return err
}
